  "footer.rbi": "RBI ᱠᱚᱢᱯᱞᱮᱱᱴ ᱠᱚ",
  "footer.built": "Build What Moves India ᱦᱮᱠᱟᱛᱷᱚᱱ ᱞᱟᱹᱜᱤᱫ ᱛᱮᱭᱟᱨ ᱟᱠᱟᱱᱟ᱾ ᱚᱠᱟ ᱥᱚᱨᱠᱟᱨᱤ ᱦᱚᱲ ᱥᱟᱶ ᱦᱚᱸ ᱵᱟᱝ ᱡᱚᱯᱚᱲᱟᱣ, ᱵᱟᱝ ᱥᱚᱫᱚᱨ ᱟᱨᱵᱟᱝ ᱡᱚᱱᱚᱲ ᱢᱮᱱᱟᱜᱼᱟ᱾ ᱡᱚᱛᱚ ᱨᱮᱯᱷᱚᱨᱮᱱᱥ ᱱᱚᱢᱵᱚᱨ ᱠᱚᱫᱚ ᱱᱚᱠᱚᱞ ᱠᱟᱱᱟ᱾",
  "start.h1": "ᱞᱟᱹᱭ ᱢᱮ ᱪᱮᱫ ᱦᱩᱭ ᱠᱟᱱᱟ᱾",
  "start.sub": "ᱟᱢᱟᱜ ᱟᱡᱟᱜ ᱟᱹᱲᱟᱹ ᱛᱮ᱾ ᱡᱮᱞᱮᱠᱟ ᱜᱮ ᱟᱢ ᱜᱷᱟᱨᱚᱸᱡᱽ ᱨᱤᱱᱤᱡ ᱢᱤᱫ ᱦᱚᱲ ᱮᱢ ᱵᱟᱲᱟᱭ ᱚᱪᱚᱭᱮᱭᱟ᱾ ᱟᱞᱮ ᱚᱱᱟ ᱫᱚ ᱡᱚᱛᱚ ᱡᱤᱱᱤᱥ ᱨᱮ ᱞᱮ ᱵᱚᱫᱚᱞᱟ ᱡᱟᱦᱟᱸ ᱯᱩᱞᱤᱥ ᱟᱨ ᱟᱢᱟᱜ ᱵᱮᱸᱠ ᱮ ᱞᱟᱹᱠᱛᱤᱭᱟ᱾",
