  "start.micStop": "ᱡᱚᱢᱮᱜᱟ — ᱢᱩᱪᱟᱹᱫ ᱠᱟᱛᱮ ᱵᱟᱲᱟᱜ ᱢᱮ",
  "start.micHint": "ᱨᱚᱲ ᱠᱟᱱᱟ",
  "start.or": "ᱵᱟᱝᱠᱷᱟᱱ ᱚᱞ ᱢᱮ",
  "start.placeholder": "ᱪᱤᱠᱟᱹ ᱞᱮᱠᱟ: ᱮᱭᱟᱭ ᱦᱤᱞᱚᱜ ᱡᱟᱸᱦᱟᱭ ᱦᱚᱲ ᱯᱷᱺᱚᱱ ᱠᱟᱛᱮᱭ ᱢᱮᱱ ᱠᱮᱫᱟ ᱡᱮ ᱩᱱᱤ ᱫᱚ ᱵᱮᱸᱠ ᱠᱷᱚᱱ ᱠᱟᱱᱟᱭ, ᱢᱮᱱ ᱠᱮᱫᱟ ᱤᱧᱟᱜ ᱠᱟᱨᱰ ᱵᱚᱱᱫᱚ ᱟᱠᱟᱱᱟ, OTP ᱠᱷᱚᱡ ᱠᱮᱫᱟ, ᱟᱨ ᱯᱮᱭᱟ ᱴᱨᱟᱱᱡᱮᱠᱥᱚᱱ ᱛᱮ ᱯᱩᱱ ᱜᱮᱞ ᱢᱤᱫ ᱥᱟᱥᱟᱭ ᱴᱟᱠᱟ ᱚᱰᱚᱠ ᱮᱱᱟ᱾",
  "start.examples": "ᱮᱦᱚᱵ ᱮᱢ ᱵᱟᱝ ᱵᱟᱰᱟᱭᱮᱫᱟ? ᱱᱚᱶᱟ ᱠᱚ ᱢᱩᱫᱽ ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱠᱩᱨᱩᱢᱩᱴᱩ ᱢᱮ",
  "start.ex1": "ᱡᱟᱸᱦᱟᱭ ᱦᱚᱲ ᱤᱧᱟᱜ ᱵᱮᱸᱠ ᱨᱤᱱᱤᱡ ᱠᱟᱱᱟ ᱢᱮᱱ ᱠᱟᱛᱮᱭ ᱯᱷᱺᱚᱱ ᱠᱮᱫᱟ ᱟᱨ OTP ᱮ ᱤᱫᱤ ᱠᱮᱫᱟ",
  "start.ex2": "ᱤᱧ ᱢᱤᱫᱴᱟᱹᱝ ᱣᱮᱵᱽᱥᱟᱭᱤᱴ ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱯᱷᱺᱚᱱ ᱞᱟᱹᱜᱤᱫ ᱠᱟᱹᱣᱰᱤ ᱮᱢ ᱠᱮᱫᱟ ᱟᱨ ᱚᱱᱟ ᱫᱚ ᱵᱟᱝ ᱥᱮᱴᱮᱨ ᱞᱮᱱᱟ",
  "start.ex3": "ᱯᱩᱞᱤᱥ ᱠᱟᱱᱟ ᱢᱮᱱ ᱠᱟᱛᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱵᱷᱤᱰᱤᱭᱳ ᱠᱚᱞ ᱠᱟᱛᱮ ᱠᱚ ᱢᱮᱱ ᱠᱮᱫᱟ ᱡᱮ ᱤᱧ ᱫᱚ ᱰᱤᱡᱤᱴᱟᱞ ᱟᱨᱮᱥᱴ ᱨᱮ ᱢﯾᱱᱟᱹᱧᱟ",
  "start.ex4": "ᱡᱟᱸᱦᱟᱭ ᱦᱚᱲ ᱤᱧᱟᱜ ᱪᱚᱵᱤ ᱠᱚ ᱵᱮᱵᱷᱟᱨ ᱠᱟᱛᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱵᱷᱩᱜᱟᱹᱜ Instagram ᱮᱠᱟᱩᱱᱴ ᱮ ᱵᱮᱱᱟᱣ ᱠᱮᱫᱟ",
  "start.ex5": "WhatsApp ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱤᱱᱵᱷᱮᱥᱴᱢᱮᱱᱴ ᱜᱩᱴ ᱤᱧᱟᱜ ᱠᱟᱹᱣᱰᱤ ᱠᱚ ᱤᱫᱤ ᱠᱮᱫᱟ ᱟᱨ ᱠᱚ ᱢᱚᱦᱚᱫ ᱮᱱᱟ",
  "start.submit": "ᱫᱷᱟᱨᱟᱭ ᱢᱮ",
  "start.analysing": "ᱟᱢᱟᱜ ᱚᱞ ᱯᱟᱲᱦᱟᱣ ᱠᱟᱱᱟ",
  "start.analysing2": "ᱚᱯᱷᱤᱥᱤᱭᱟᱞ ᱠᱮᱴᱚᱜᱚᱨᱤ ᱥᱟᱶ ᱢᱮᱥᱟᱭᱮᱫᱟ",
  "start.analysing3": "ᱟᱢᱟᱜ ᱰᱮᱰᱞᱟᱭᱤᱱ ᱜᱚᱲᱤ ᱮᱦᱚᱵ ᱠᱟᱱᱟ",
  "start.privacy": "ᱟᱢᱟᱜ Aadhaar ᱱᱚᱢᱵᱚᱨ, PAN, ᱠᱟᱨᱰ PIN, ᱯᱟᱥᱣᱟᱰ ᱵᱟᱝᱠᱷᱟᱱ ᱡᱟᱸᱦᱟᱱᱟᱜ OTP ᱟᱞᱚᱢ ᱚᱞᱟ᱾ ᱟᱞᱮ ᱚᱱᱟ ᱠᱚ ᱫᱚ ᱡᱟᱦᱟᱸ ᱡᱚᱠᱷᱚᱡ ᱵᱟᱞᱮ ᱯᱟᱱᱛᱮᱭᱟ᱾",
  "start.tooShort": "ᱟᱨᱦᱚᱸ ᱠᱟᱹᱴᱤᱡ ᱡᱟᱯᱟᱜ ᱢᱮ — ᱢᱤᱫᱴᱟᱹᱝ ᱟᱹᱲᱟᱹ ᱦᱚᱸ ᱱᱟᱯᱟᱭ ᱛᱮ ᱵᱟᱰᱟᱭ ᱚᱪᱚ ᱞᱟᱹᱜᱤᱫ ᱜᱚᱲᱚ ᱟᱞᱮᱭᱟ᱾",
