  "start.voiceUnsupported": "ᱱᱚᱶᱟ ᱵᱽᱨᱟᱣᱡᱚᱨ ᱫᱚ ᱨᱮᱠᱚᱰ ᱫᱟᱲᱮᱭᱟᱜ-ᱟ᱾ ᱫᱚᱭᱟ ᱠᱟᱛᱮ ᱚᱞ ᱢᱮ᱾",
