  "rep.r.sub": "ᱱᱚᱸᱰᱮ ᱠᱷᱚᱱ ᱡᱟᱦᱟᱸ ᱜᱮ ᱵᱚᱫᱚᱞ ᱢᱮ᱾ ᱡᱟᱦᱟᱸ ᱜᱮ ᱟᱢᱢᱚ ᱴᱷᱤᱠᱟ ᱚᱱᱟ ᱫᱚ ᱵᱟᱭ ᱯᱟᱨᱚᱢᱚᱜᱼᱟ᱾",
  "rep.r.needed": "ᱵᱷᱮᱜᱟᱨ ᱞᱟᱹᱜᱤᱫ ᱱᱤᱛ ᱦᱚᱸ ᱞᱟᱹᱠᱛᱤᱜ ᱠᱟᱱᱟ",
  "rep.r.agree": "ᱤᱧᱟᱜ ᱵᱟᱰᱟᱭ ᱞᱮᱠᱟᱛᱮ ᱤᱧ ᱡᱟᱦᱟᱸ ᱵᱟᱰᱟᱭ ᱡᱤᱱᱤᱥ ᱤᱧ ᱮᱢ ᱟᱠᱟᱫᱟ ᱚᱱᱟ ᱫᱚ ᱥᱚᱛ ᱜᱮᱭᱟ᱾",
  "rep.r.submit": "ᱚᱵᱷᱤᱡᱳᱜᱽ ᱵᱷᱮᱜᱟᱨ ᱢᱮ",
