  "esc.pickState": "ᱚᱯᱷᱤᱥᱚᱨ ᱠᱚ ᱧᱮᱞ ᱞᱟᱹᱜᱤᱫ ᱟᱢᱟᱜ ᱯᱚᱱᱚᱛ ᱵᱟᱪᱷաᱣ ᱢᱮ",
  "esc.source": "ᱚᱯᱷᱤᱥᱚᱨ ᱵᱤᱵᱚᱨᱚᱱ ᱡᱮᱞᱮᱠᱟ ᱯᱤᱲᱤᱛ ᱠᱚ ᱞᱟᱹᱜᱤᱫ ᱯᱟᱨᱥᱟᱞ ᱟᱠᱟᱱᱟ",
