  "doc.print": "ᱯᱨᱤᱱᱴ",
  "doc.inEnglish": "ᱤᱝᱞᱤᱥ ᱛᱮ ᱵᱷᱮᱜᱟᱨ ᱮᱱᱟ",
  "doc.inYourLang": "ᱟᱢᱟᱜ ᱯᱟᱹᱨᱥᱤ ᱛᱮ ᱯᱟᱲᱦᱟᱣ ᱢᱮ",
  "doc.whyEnglish": "ᱯᱩᱞᱤᱥ ᱥᱴᱮᱥᱚᱱ ᱟᱨ ᱵᱮᱸᱠ ᱠᱚ ᱫᱚ ᱤᱝᱞᱤᱥ ᱛᱮ ᱠᱟᱹᱢᱤᱭᱟ᱾ ᱟᱢ ᱡᱟᱦᱟᱸᱢ  सही ᱠᱟᱱᱟ ᱚᱱᱟ ᱦᱚᱸ ᱯᱟᱲᱦᱟᱣ ᱫᱟᱲᱮᱭᱟᱜ ᱢᱟ, ᱚᱱᱟ ᱠᱷᱟᱹᱛᱤᱨ ᱞᱮ ᱫᱮᱠᱷᱟᱣ ᱟᱠᱟᱫ ᱟ᱾",
  "doc.readyLabel": "तयाᱨ ᱜᱮᱭᱟ",
  "doc.needsLabel": "ᱵᱟᱹᱲᱛᱤ ᱵᱤᱵᱚᱨᱚᱱ ᱞᱟᱹᱠᱛᱤᱜ ᱠᱟᱱᱟ",
  "doc.needs": "ᱱᱚᱣᱟ ᱯᱩᱭᱞᱩ ᱡᱚᱲᱟᱣ ᱢᱮ",
  "doc.ncrp.t": "NCRP অভিযোগ ᱵᱤᱵᱚᱨᱚᱱ",
  "doc.ncrp.b": "cybercrime.gov.in ᱨᱮᱱᱟᱜ ᱵᱤᱵᱚᱨᱚᱱ ᱵᱟᱠᱥᱟ ᱨᱮ ᱱᱚᱣᱟ ᱥᱤᱫᱷᱟᱹ ᱯᱮᱥᱴ ᱢᱮ᱾ ᱱᱚᱣᱟ ᱫᱚ 200-অক্ষর ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱠᱟᱱᱟ ᱟᱨ ᱯᱳᱨᱴᱟᱞ ᱵᱟᱭ ᱦᱟᱛᱟᱣᱟ ᱚᱱᱠᱟᱱ ᱵᱤᱨᱟᱹᱢ ᱪᱤᱱᱦᱟᱹ ᱵᱟᱹᱱᱩᱜᱼᱟ᱾",
  "doc.script.t": "ᱟᱢᱟᱜ 1930 ᱠᱚᱞ ᱥᱠᱨիᱯᱴ",
  "doc.script.b": "ᱱᱚᱣᱟ ᱯᱟᱲᱦᱟᱣ ᱢᱮ᱾ ᱚᱯᱚᱨᱮᱴᱚᱨ ᱱᱚᱣᱟ ᱠᱟᱛᱷᱟ ᱠᱚ ᱱᱚᱣᱟ ᱞᱮᱠᱟᱛᱮ ᱞᱟᱹᱠᱛᱤᱜ ᱠᱟᱱᱟ, ᱟᱨ ᱡᱩᱫᱤ ᱟᱢ ᱴᱷᱮᱱ तयाᱨ ᱛᱟᱦᱮᱸᱱᱟ ᱮᱱᱠᱷᱟᱱ ᱯᱷᱳᱱ ᱞᱚᱜᱚᱱ ᱪᱟᱞᱟᱜᱼᱟ᱾",
  "doc.bank.t": "ᱵᱮᱸᱠ ᱴᱷᱮᱱ ᱪᱤᱴᱷᱤ",
  "doc.bank.b": "ᱤᱢᱮᱞ ᱢᱮ ᱟᱨ ᱵᱨᱟᱸᱪ ᱨᱮ ᱢᱤᱫᱴᱟᱹᱝ ᱯᱨᱤᱱᱴ ᱠᱟᱜᱚᱡᱽ ᱮᱢ ᱢᱮ᱾ ᱱᱚᱣᱟ ᱜᱮ ᱟᱢᱟᱜ ᱫᱟᱭᱤᱠ ᱫᱚ  सुनᱭ ᱮᱫᱟ — ᱱᱚᱣᱟ ᱨᱮᱱᱟᱜ ᱥᱤᱠᱟᱹᱨ ᱟᱨ ᱢᱟᱦᱤᱛ ᱦᱟᱛᱟᱣ ᱢᱮ᱾",
